.base-cta {
  display: inline-flex;
  align-items: center;
  border: 0;
  cursor: pointer;
  background: var(--base-blue, #2b2cf6);
  color: #fff;
  font-family: inherit;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1;
  padding: 17px 26px;
  border-radius: 16px;
  text-decoration: none;
  box-shadow:
    0 1px 2px rgba(20, 24, 60, 0.12),
    0 12px 30px -16px rgba(43, 44, 246, 0.5);
  transition:
    box-shadow 0.28s cubic-bezier(0.2, 0.7, 0.2, 1),
    filter 0.28s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.base-cta:is(:hover, :focus-visible) {
  box-shadow:
    0 2px 4px rgba(20, 24, 60, 0.14),
    0 18px 38px -16px rgba(43, 44, 246, 0.6);
}
.base-cta:active {
  transform: translateY(0.5px);
}
.base-cta:focus-visible {
  outline: 3px solid rgba(43, 44, 246, 0.35);
  outline-offset: 3px;
}

.base-cta__chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 0;
  height: 26px;
  margin-right: 0;
  border-radius: 8px;
  background: #fff;
  opacity: 0;
  transform: scale(0.4);
  transform-origin: left center;
  overflow: hidden;
  transition:
    width 0.3s cubic-bezier(0.2, 0.7, 0.2, 1),
    margin-right 0.3s cubic-bezier(0.2, 0.7, 0.2, 1),
    opacity 0.22s cubic-bezier(0.2, 0.7, 0.2, 1),
    transform 0.3s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.base-cta:is(:hover, :focus-visible) .base-cta__chip {
  width: 26px;
  margin-right: 12px;
  opacity: 1;
  transform: scale(1);
}

.base-cta__label {
  display: inline-block;
  white-space: nowrap;
}

.base-cta__arrow {
  display: inline-flex;
  width: 20px;
  margin-left: 10px;
  opacity: 1;
  transform: translateX(0);
  transition:
    width 0.3s cubic-bezier(0.2, 0.7, 0.2, 1),
    margin-left 0.3s cubic-bezier(0.2, 0.7, 0.2, 1),
    opacity 0.2s cubic-bezier(0.2, 0.7, 0.2, 1),
    transform 0.3s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.base-cta:is(:hover, :focus-visible) .base-cta__arrow {
  width: 0;
  margin-left: 0;
  opacity: 0;
  transform: translateX(10px);
}
.base-cta__arrow svg {
  display: block;
}

@media (prefers-reduced-motion: reduce) {
  .base-cta,
  .base-cta__chip,
  .base-cta__arrow {
    transition: none;
  }
}

"use client";
import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";
import "./base-cta-button.css";
export type BaseCtaButtonProps = ComponentProps<"button">;
export function BaseCtaButton({
  children = "Start building",
  className,
  ...props
}: BaseCtaButtonProps) {
  return (
    <button
      type="button"
      {...props}
      data-slot="base-cta-button"
      className={cn("base-cta", className)}
    >
      <span className="base-cta__chip" aria-hidden="true" />
      <span className="base-cta__label">{children}</span>
      <span className="base-cta__arrow" aria-hidden="true">
        <svg width="20" height="16" viewBox="0 0 20 16" fill="none">
          <path
            d="M2 8h15M11 2l6 6-6 6"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </span>
    </button>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
